previewCss:
.darma-loader-elevator-lift {
  position: relative;
  width: 30px;
  height: 52px;
  border: 2px solid #c7d2fe;
  border-radius: 4px;
  box-sizing: border-box;
  overflow: hidden;
  background: repeating-linear-gradient(transparent 0 12px, #c7d2fe 12px 13px);
}
.darma-loader-elevator-lift i {
  position: absolute;
  left: 4px;
  right: 4px;
  top: 4px;
  height: 12px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-elevator-lift-elev 1.8s ease-in-out infinite;
}
.darma-loader-elevator-lift i::before {
  content: "";
  position: absolute;
  top: 2px;
  bottom: 2px;
  left: 50%;
  width: 1px;
  background: #e0e7ff;
}
@keyframes darma-loader-elevator-lift-elev {
  0%, 100% { top: 4px; }
  50% { top: calc(100% - 16px); }
}

